import { Component, ElementRef, QueryList, ViewChildren } from '@angular/core';

type Player = 'X' | 'O';
type Cell = Player | null;
type Board = Cell[];
type NavigationKey = 'ArrowLeft' | 'ArrowRight' | 'ArrowUp' | 'ArrowDown' | 'Home' | 'End';

const WINNING_LINES: number[][] = [
  [0, 1, 2],
  [3, 4, 5],
  [6, 7, 8],
  [0, 3, 6],
  [1, 4, 7],
  [2, 5, 8],
  [0, 4, 8],
  [2, 4, 6]
];

const NAVIGATION_KEYS: NavigationKey[] = [
  'ArrowLeft',
  'ArrowRight',
  'ArrowUp',
  'ArrowDown',
  'Home',
  'End'
];

function createEmptyBoard(): Board {
  return Array.from({ length: 9 }, () => null);
}

function calculateWinningLine(board: Board): number[] | null {
  for (const line of WINNING_LINES) {
    const [first, second, third] = line;
    const mark = board[first];
    if (mark && mark === board[second] && mark === board[third]) {
      return line;
    }
  }

  return null;
}

@Component({
  selector: 'app-root',
  standalone: true,
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  @ViewChildren('cellButton') cellButtons!: QueryList<ElementRef<HTMLButtonElement>>;

  history: Board[] = [createEmptyBoard()];
  cursor = 0;
  focusIndex = 0;

  get board(): Board {
    return this.history[this.cursor];
  }

  get currentPlayer(): Player {
    return this.cursor % 2 === 0 ? 'X' : 'O';
  }

  get winningLine(): number[] | null {
    return calculateWinningLine(this.board);
  }

  get winner(): Player | null {
    const line = this.winningLine;
    return line ? this.board[line[0]] as Player : null;
  }

  get isDraw(): boolean {
    return !this.winner && this.board.every((cell) => cell !== null);
  }

  get isGameOver(): boolean {
    return this.winner !== null || this.isDraw;
  }

  get status(): string {
    if (this.winner) return 'Winner: ' + this.winner;
    if (this.isDraw) return 'Draw';
    return 'Next: ' + this.currentPlayer;
  }

  get canUndo(): boolean {
    return this.cursor > 0;
  }

  get canRedo(): boolean {
    return this.cursor < this.history.length - 1;
  }

  cellId(index: number): string {
    return 'tic-tac-toe-cell-' + index;
  }

  cellLabel(index: number, cell: Cell): string {
    const row = Math.floor(index / 3) + 1;
    const column = (index % 3) + 1;
    return 'Row ' + row + ', column ' + column + ': ' + (cell ?? 'empty');
  }

  isWinningCell(index: number): boolean {
    return this.winningLine?.includes(index) ?? false;
  }

  isCellDisabled(index: number): boolean {
    return this.isGameOver || this.board[index] !== null;
  }

  play(index: number): void {
    if (this.isGameOver || this.board[index] !== null) return;

    const nextBoard = this.board.slice();
    nextBoard[index] = this.currentPlayer;
    const retainedHistory = this.history.slice(0, this.cursor + 1);
    this.history = [...retainedHistory, nextBoard];
    this.cursor += 1;
  }

  undo(): void {
    if (!this.canUndo) return;
    this.cursor -= 1;
  }

  redo(): void {
    if (!this.canRedo) return;
    this.cursor += 1;
  }

  reset(): void {
    this.history = [createEmptyBoard()];
    this.cursor = 0;
    this.focusIndex = 0;
  }

  setFocusIndex(index: number): void {
    this.focusIndex = index;
  }

  focusCell(index: number): void {
    this.focusIndex = index;
    this.cellButtons.get(index)?.nativeElement.focus();
  }

  onCellKeydown(event: KeyboardEvent, index: number): void {
    const key = event.key as NavigationKey;
    if (!NAVIGATION_KEYS.includes(key)) return;

    event.preventDefault();
    const row = Math.floor(index / 3);
    const column = index % 3;
    let nextIndex = index;

    if (key === 'ArrowLeft') nextIndex = row * 3 + (column + 2) % 3;
    else if (key === 'ArrowRight') nextIndex = row * 3 + (column + 1) % 3;
    else if (key === 'ArrowUp') nextIndex = ((row + 2) % 3) * 3 + column;
    else if (key === 'ArrowDown') nextIndex = ((row + 1) % 3) * 3 + column;
    else if (key === 'Home') nextIndex = row * 3;
    else if (key === 'End') nextIndex = row * 3 + 2;

    this.focusCell(nextIndex);
  }
}

