:host {
  display: block;
  min-height: 100%;
}

* {
  box-sizing: border-box;
}

.page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background: #0a0a0a;
  color: #e5e7eb;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

.card {
  width: 100%;
  max-width: 520px;
  padding: 18px;
  display: grid;
  gap: 14px;
  border: 1px solid #1f2937;
  border-radius: 14px;
  background: #0b1020;
}

.title {
  margin: 0;
  font-size: 18px;
  font-weight: 800;
}

.subtitle {
  margin: 0;
  color: #9ca3af;
  font-size: 12px;
}

.status {
  padding: 10px 12px;
  border: 1px solid #1f2937;
  border-radius: 12px;
  background: #0a0f1e;
  font-weight: 700;
}

.board {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.cell-slot {
  min-width: 0;
  aspect-ratio: 1 / 1;
}

.cell {
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  border: 1px solid rgba(31, 41, 55, .7);
  border-radius: 14px;
  background: #0a0f1e;
  color: #e5e7eb;
  font-size: 34px;
  font-weight: 900;
  cursor: pointer;
}

.cell[aria-disabled="true"] {
  cursor: not-allowed;
}

.cell.winning {
  border-color: #a3e635;
  background: #1a2e05;
  color: #ecfccb;
}

.cell:focus-visible {
  outline: 3px solid #facc15;
  outline-offset: 2px;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.ghost {
  padding: 10px 14px;
  border: 1px solid #374151;
  border-radius: 12px;
  background: transparent;
  color: #e5e7eb;
  font-weight: 800;
  cursor: pointer;
}

.ghost:disabled {
  opacity: .45;
  cursor: not-allowed;
}

@media (max-width: 520px) {
  .page {
    padding: 14px;
  }
}

